import React, { FormEvent, useState } from 'react';

import { _t } from '../../../../languageHandler';
import AccessibleButton from '../../elements/AccessibleButton';
import Spinner from '../../elements/Spinner';
import Heading from '../../typography/Heading';
import { DeviceWithVerification } from './types';

interface Props {
    device: DeviceWithVerification;
    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
}

export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [deviceName, setDeviceName] = useState(device.display_name ?? device.device_id);
    const [isSaving, setIsSaving] = useState(false);
    const [hasError, setHasError] = useState(false);
    const [savedDeviceName, setSavedDeviceName] = useState<string>();

    const visibleName = savedDeviceName ?? device.display_name ?? device.device_id;

    const startEditing = (): void => {
        setDeviceName(visibleName);
        setHasError(false);
        setIsEditing(true);
    };

    const cancelEditing = (): void => {
        setDeviceName(visibleName);
        setHasError(false);
        setIsEditing(false);
    };

    const submit = async (event?: FormEvent): Promise<void> => {
        event?.preventDefault();
        if (deviceName === visibleName) {
            setIsEditing(false);
            return;
        }

        setIsSaving(true);
        setHasError(false);
        try {
            await saveDeviceName(device.device_id, deviceName);
            setSavedDeviceName(deviceName);
            setIsEditing(false);
        } catch {
            setHasError(true);
        } finally {
            setIsSaving(false);
        }
    };

    if (isEditing) {
        return <div data-testid='device-detail-heading-edit'>
            <form onSubmit={submit}>
                <label>
                    { _t('Session name') }
                    <input
                        data-testid='device-detail-name-input'
                        type='text'
                        value={deviceName}
                        maxLength={100}
                        autoFocus
                        disabled={isSaving}
                        onChange={event => setDeviceName(event.target.value)}
                    />
                </label>
                <p>{ _t('Session names may be visible to people you communicate with.') }</p>
                { hasError && <p role='alert' data-testid='device-detail-name-error'>
                    { _t('Failed to set display name.') }
                </p> }
                { isSaving && <Spinner w={16} h={16} /> }
                <AccessibleButton
                    kind='primary'
                    onClick={() => submit()}
                    disabled={isSaving}
                    data-testid='device-detail-name-save'
                >
                    { _t('Save') }
                </AccessibleButton>
                <AccessibleButton
                    kind='secondary'
                    onClick={cancelEditing}
                    disabled={isSaving}
                    data-testid='device-detail-name-cancel'
                >
                    { _t('Cancel') }
                </AccessibleButton>
            </form>
        </div>;
    }

    return <div data-testid='device-detail-heading-read'>
        <Heading size='h3'>{ visibleName }</Heading>
        <AccessibleButton
            kind='link_inline'
            onClick={startEditing}
            data-testid='device-detail-name-rename'
        >
            { _t('Rename') }
        </AccessibleButton>
    </div>;
};

